 "content": "def transform(grid):
    # Convert the six uppermost 2x2 objects to 8; others remain 2.
    out = [row[:] for row in grid]
    comps = []
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==2 and q not in seen:
                        seen.add(q); stack.append(q)
            comps.append(cells)
    # Demo shows the objects above the horizontal midline recolored, plus their counterparts?
    # provisional criterion: top three objects in reading order become 8.
    comps.sort(key=lambda cells: min((y,x) for y,x in cells))
    for cells in comps[:3]:
        for y,x in cells: out[y][x]=8
    return out
